/* ============ Design tokens ============ */
:root {
  --bg: #f3f5f9;
  --panel: #ffffff;
  --ink: #0f172a;
  --ink-2: #475569;
  --ink-3: #8a97ab;
  --line: #e2e8f0;
  --line-2: #cbd5e1;
  --accent: #2563eb;
  --accent-deep: #1d4ed8;
  --accent-tint: #eef4ff;
  --done: #059669;
  --done-tint: #f0fdf4;
  --done-line: #bbf7d0;
  --warn-ink: #92400e;
  --warn-bg: #fffbeb;
  --warn-line: #fde68a;
  --risk: #dc2626;
  --risk-ink: #991b1b;
  --risk-bg: #fef2f2;
  --risk-line: #fecaca;
  --radius: 12px;
  --radius-s: 9px;
  --shadow: 0 1px 2px rgba(15, 23, 42, .05), 0 8px 24px rgba(15, 23, 42, .05);
  --font: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", "Segoe UI", system-ui, sans-serif;
  --mono: ui-monospace, "Cascadia Code", Consolas, monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
*:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }

/* ============ Topbar ============ */
.topbar {
