.rail-item.locked { opacity: .5; cursor: default; }
.rail-item.locked:hover { background: transparent; }
.rail-item .step-title { flex: 1; min-width: 0; }
.rail-item .code { color: var(--ink-3); font-family: var(--mono); font-size: 11.5px; flex: none; }

