.rail-phase-head .count { font-weight: 600; font-variant-numeric: tabular-nums; letter-spacing: 0; }
.rail-item {
  display: flex; align-items: center; gap: 10px; width: 100%;
  text-align: left; padding: 9px 10px;
  border: none; border-left: 3px solid transparent; border-radius: var(--radius-s);
  background: transparent; cursor: pointer;
  font: inherit; font-size: 13.5px; line-height: 1.45; color: var(--ink-2);
}
.rail-item:hover { background: #f1f5f9; }
.rail-item.selected { background: var(--accent-tint); }
