  position: fixed; inset: 0; z-index: 50;
  background: rgba(15, 23, 42, .55);
  display: grid; place-items: center; padding: 20px;
}
.modal {
  background: #fff; border-radius: 14px;
  width: 580px; max-width: 100%; max-height: 90vh; overflow-y: auto;
  padding: 26px 30px 28px;
  box-shadow: 0 24px 64px rgba(2, 6, 23, .35);
}
.modal h2 { margin: 0; font-size: 18.5px; line-height: 1.5; }
.modal .sub { color: var(--ink-2); font-size: 14px; line-height: 1.75; margin-top: 10px; }
.modal .risk-banner { margin-top: 18px; }
.modal .recovery { margin-top: 14px; }
.phrase-row { margin-top: 20px; }
.phrase-row label { display: block; font-size: 13.5px; margin-bottom: 9px; line-height: 1.6; }
code.phrase {
  background: #f1f5f9; border: 1px solid var(--line);
  border-radius: 6px; padding: 1px 8px;
  font-family: var(--mono); font-size: 12.5px; color: var(--ink);
}
.phrase-input {
  width: 100%; font: inherit; font-size: 15px;
  padding: 10px 13px; border: 1.5px solid var(--line-2); border-radius: 9px;
}
.phrase-input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px rgba(37, 99, 235, .15); }
.modal-error { display: none; color: #b91c1c; font-size: 13px; margin-top: 9px; }
.modal-error.show { display: block; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 24px; }

/* ============ Toast ============ */
.toast {
  position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%);
  background: #0f172a; color: #f1f5f9;
  padding: 10px 20px; border-radius: 10px; font-size: 13.5px;
  box-shadow: 0 12px 32px rgba(2, 6, 23, .35); z-index: 60;
}

@media (max-width: 1280px) {
  .layout { grid-template-columns: 262px minmax(0, 1fr) 280px; }
  .meta { display: none; }
}
@media (max-width: 1020px) {
  .layout { grid-template-columns: 1fr; height: auto; }
  .detail { overflow: visible; }
}

/* ============ Design tokens ============ */
:root {
  --bg: #f3f5f9;
  --panel: #ffffff;
  --ink: #0f172a;
  --ink-2: #475569;
  --ink-3: #5a6b80; /* ≥4.5:1 on white / tint / warn backgrounds (AA) */
  --line: #e2e8f0;
  --line-2: #cbd5e1;
  --accent: #2563eb;
  --accent-deep: #1d4ed8;
  --accent-tint: #eef4ff;
  --done: #059669;
  --done-tint: #f0fdf4;
  --done-line: #bbf7d0;
  --warn-ink: #92400e;
  --warn-bg: #fffbeb;
  --warn-line: #fde68a;
  --risk: #dc2626;
  --risk-ink: #991b1b;
  --risk-bg: #fef2f2;
  --risk-line: #fecaca;
  --radius: 12px;
  --radius-s: 9px;
  --shadow: 0 1px 2px rgba(15, 23, 42, .05), 0 8px 24px rgba(15, 23, 42, .05);
  --font: "PingFang SC", "Microsoft YaHei", "Noto Sans SC", "Segoe UI", system-ui, sans-serif;
  --mono: ui-monospace, "Cascadia Code", Consolas, monospace;
}

* { box-sizing: border-box; }
html, body { height: 100%; }
body {
  margin: 0;
  font-family: var(--font);
  font-size: 15px;
  color: var(--ink);
  background: var(--bg);
  -webkit-font-smoothing: antialiased;
}
*:focus-visible { outline: 2px solid var(--accent); outline-offset: 2px; border-radius: 4px; }

/* ============ Topbar ============ */
.topbar {
  position: sticky; top: 0; z-index: 10;
  display: flex; align-items: center; gap: 18px;
  height: 58px; padding: 0 20px;
  background: #0f172a; color: #e2e8f0;
}
.brand { display: flex; align-items: center; gap: 9px; font-weight: 650; font-size: 15.5px; white-space: nowrap; }
.brand-mark { color: #60a5fa; font-size: 17px; }
.brand-sub {
  color: #94a3b8; font-weight: 500; font-size: 12px;
  border: 1px solid #334155; border-radius: 999px; padding: 2px 9px;
}
.meta { display: flex; gap: 8px; color: #cbd5e1; font-size: 12.5px; }
.meta-item {
  padding: 3px 10px; background: #1e293b; border-radius: 6px;
  font-variant-numeric: tabular-nums; white-space: nowrap;
}
.progress-wrap { margin-left: auto; display: flex; align-items: center; gap: 10px; }
.progress-bar { width: 170px; height: 6px; background: #334155; border-radius: 999px; overflow: hidden; }
#progressFill { height: 100%; width: 0; background: linear-gradient(90deg, #38bdf8, #34d399); transition: width .35s ease; }
#progressText { font-size: 12.5px; color: #94a3b8; font-variant-numeric: tabular-nums; white-space: nowrap; }
.topbar-actions { display: flex; gap: 8px; }
.global-actions {
  position: fixed; bottom: 14px; right: 20px; z-index: 11;
  display: flex; gap: 8px; padding: 6px;
  background: #fff; border: 1px solid var(--line); border-radius: 12px;
  box-shadow: 0 8px 24px rgba(15, 23, 42, .14);
}
.btn.footer-btn { background: #fff; color: var(--ink-2); border-color: var(--line-2); }
.btn.footer-btn:not(:disabled):hover { background: #f1f5f9; }

/* ============ Buttons ============ */
.btn {
  font: inherit; font-size: 13.5px; cursor: pointer;
  border: 1px solid transparent; border-radius: 8px;
  padding: 8px 15px; transition: background .15s, border-color .15s, opacity .15s;
  white-space: nowrap;
}
.btn:disabled { opacity: .45; cursor: not-allowed; }
.btn.primary { background: var(--accent); color: #fff; }
.btn.primary:not(:disabled):hover { background: var(--accent-deep); }
.btn.ghost { background: transparent; color: #cbd5e1; border-color: #334155; }
.btn.ghost:not(:disabled):hover { background: #1e293b; }
.btn.tonal { background: var(--accent-tint); color: var(--accent-deep); border-color: #c7dbff; }
.btn.tonal:not(:disabled):hover { background: #dce8ff; }
.btn.risk { background: #fff; color: #b91c1c; border-color: #fca5a5; }
.btn.risk:not(:disabled):hover { background: var(--risk-bg); }
.btn.big { font-size: 14.5px; padding: 11px 22px; border-radius: 10px; }

/* ============ Layout ============ */
.layout {
  display: grid;
  grid-template-columns: 298px minmax(0, 1fr) 322px;
  gap: 14px;
  padding: 14px;
  height: calc(100vh - 58px);
}
.panel {
  background: var(--panel); border: 1px solid var(--line);
  border-radius: var(--radius); box-shadow: var(--shadow);
  overflow-y: auto;
}

