.rail-phase-head {
  display: flex; justify-content: space-between; align-items: baseline;
  padding: 4px 10px;
  color: var(--ink-3); font-size: 12px; font-weight: 700;
  letter-spacing: .08em;
}
.rail-phase-head .count { font-weight: 600; font-variant-numeric: tabular-nums; letter-spacing: 0; }
.rail-item {
  display: flex; align-items: center; gap: 9px; width: 100%;
  text-align: left; padding: 5px 10px;
  border: none; border-left: 3px solid transparent; border-radius: var(--radius-s);
  background: transparent; cursor: pointer;
  font: inherit; font-size: 13px; line-height: 1.4; color: var(--ink-2);
}
.rail-item:hover { background: #f1f5f9; }
.rail-item.selected { background: var(--accent-tint); }
.rail-item.current { background: var(--accent-tint); border-left-color: var(--accent); color: var(--ink); }
.rail-item.locked { color: var(--ink-3); cursor: default; } /* 不用 opacity：避免混合后对比度跌破 AA */
.rail-item.locked:hover { background: transparent; }
.rail-item .step-title { flex: 1; min-width: 0; }
.rail-item .code { color: var(--ink-3); font-family: var(--mono); font-size: 12px; flex: none; }

.dot {
  width: 18px; height: 18px; flex: none;
  border-radius: 50%; border: 2px solid var(--line-2);
  display: grid; place-items: center;
  font-size: 10.5px; font-weight: 700; color: transparent; background: #fff;
}
.dot.done { background: var(--done); border-color: var(--done); color: #fff; }
.dot.current { border-color: var(--accent); }
