  padding: 30px 36px 36px; min-height: 100%;
}
.card-head .phase-line { color: var(--ink-3); font-size: 13px; }
.card-head h1 { margin: 6px 0 0; font-size: 23px; line-height: 1.4; }
.head-chips { display: flex; gap: 8px; margin-top: 12px; align-items: center; flex-wrap: wrap; }
.status-chip { font-size: 11.5px; font-weight: 600; padding: 2.5px 10px; border-radius: 999px; }
.status-chip.current { color: var(--accent-deep); background: var(--accent-tint); }
.status-chip.done { color: #065f46; background: var(--done-tint); }
.status-chip.locked { color: var(--ink-2); background: #f1f5f9; }

.risk-banner {
  display: flex; gap: 10px; align-items: flex-start;
  background: var(--risk-bg); border: 1px solid var(--risk-line);
  color: var(--risk-ink); font-size: 14px; line-height: 1.65;
  padding: 13px 16px; border-radius: 10px; margin-top: 22px;
}
.risk-banner .icon { flex: none; font-size: 16px; }

.sec { margin-top: 28px; }
.sec > h2 {
  margin: 0 0 12px; font-size: 12px; font-weight: 700;
  letter-spacing: .08em; color: var(--ink-3);
}
ol.instr { margin: 0; padding-left: 22px; display: grid; gap: 9px; font-size: 15px; line-height: 1.75; }

.contingency {
  background: var(--warn-bg); border: 1px solid var(--warn-line);
  border-radius: 10px; padding: 14px 18px; font-size: 14px; color: #78350f; line-height: 1.65;
}
.contingency ul { margin: 8px 0 0; padding-left: 18px; display: grid; gap: 6px; }
.contingency b { color: var(--warn-ink); }

.gate { border: 1px solid var(--line); border-radius: 10px; padding: 4px 20px 12px; }
.check-row {
  display: flex; gap: 12px; align-items: flex-start;
  padding: 12px 0; border-bottom: 1px dashed var(--line);
  cursor: pointer; font-size: 15px; line-height: 1.6;
}
.check-row:last-of-type { border-bottom: none; }
.check-row input[type="checkbox"] {
  width: 17px; height: 17px; margin: 3px 0 0; flex: none;
  accent-color: var(--accent); cursor: pointer;
}
.check-row.disabled { opacity: .6; cursor: default; }
.gate-hint { padding: 10px 2px 0; font-size: 13px; color: var(--warn-ink); }
.gate-hint.ok { color: var(--done); }

.recovery {
  border: 1px solid var(--warn-line); background: #fffdf5;
  border-radius: 10px; padding: 16px 20px 18px;
}
.recovery h3 {
  margin: 0; font-size: 14.5px; color: var(--warn-ink);
  display: flex; align-items: center; gap: 8px;
}
.recovery .impact { font-size: 13.5px; color: var(--ink-2); margin: 9px 0 2px; line-height: 1.7; }
.recovery ol { margin: 8px 0 0; padding-left: 20px; display: grid; gap: 5px; font-size: 14px; line-height: 1.65; }
.recovery-foot { margin-top: 15px; display: flex; align-items: center; gap: 12px; flex-wrap: wrap; }
.recovery-note { font-size: 12.5px; color: var(--ink-3); line-height: 1.6; }

.action-row { margin-top: 32px; display: flex; gap: 12px; align-items: center; flex-wrap: wrap; }
.action-note { font-size: 13px; color: var(--ink-3); }

.locked-note {
  margin-top: 28px; background: #f8fafc; border: 1px dashed var(--line-2);
  color: var(--ink-2); padding: 14px 18px; border-radius: 10px; font-size: 14px; line-height: 1.7;
}

.done-hero {
  background: linear-gradient(180deg, var(--done-tint), #fff 70%);
  border: 1px solid var(--done-line); border-radius: var(--radius);
  box-shadow: var(--shadow); padding: 44px 48px; min-height: 100%;
}
.done-hero h1 { margin: 10px 0 0; font-size: 26px; color: #065f46; }
.done-hero .lead { color: var(--ink-2); font-size: 15px; margin-top: 10px; line-height: 1.8; }
.done-stats { display: flex; gap: 40px; margin: 28px 0 6px; flex-wrap: wrap; }
.stat b { display: block; font-size: 28px; font-variant-numeric: tabular-nums; }
.stat span { font-size: 12.5px; color: var(--ink-2); }

/* ============ Log panel ============ */
.logpanel { padding: 14px 16px 60px; } /* 底部留出全局工具条空间 */
.logpanel h2 {
  margin: 4px 0 12px; font-size: 12px; font-weight: 700;
  letter-spacing: .08em; color: var(--ink-3);
  display: flex; justify-content: space-between; align-items: baseline;
}
.log-empty {
  color: var(--ink-3); font-size: 13px; line-height: 1.8; text-align: center;
  border: 1px dashed var(--line-2); border-radius: 10px; padding: 30px 12px; margin-top: 8px;
}
.log-item { padding: 10px 2px; border-bottom: 1px solid #f1f5f9; }
.log-item:last-child { border-bottom: none; }
.log-top { display: flex; align-items: center; gap: 8px; margin-bottom: 3px; }
.log-time { color: var(--ink-3); font-family: var(--mono); font-size: 11px; }
.badge { font-size: 10.5px; font-weight: 600; padding: 1px 8px; border-radius: 999px; border: 1px solid; }
.badge.normal { color: var(--ink-2); border-color: var(--line); background: #f8fafc; }
.badge.verify { color: var(--warn-ink); border-color: var(--warn-line); background: var(--warn-bg); }
.badge.irreversible { color: #b91c1c; border-color: #fca5a5; background: var(--risk-bg); }
.badge.recovery { color: #92400e; border-color: var(--warn-line); background: var(--warn-bg); }
.log-text { font-size: 13px; color: var(--ink); line-height: 1.6; }
.log-recover {
  margin-top: 6px;
  font: inherit; font-size: 12px; cursor: pointer;
  color: var(--warn-ink); background: transparent;
  border: 1px solid var(--warn-line); border-radius: 7px; padding: 3px 10px;
}
.log-recover:hover { background: var(--warn-bg); }

/* ============ Modal ============ */
.modal-overlay {
  position: fixed; inset: 0; z-index: 50;
  background: rgba(15, 23, 42, .55);
  display: grid; place-items: center; padding: 20px;
}
.modal {
  background: #fff; border-radius: 14px;
  width: 580px; max-width: 100%; max-height: 90vh; overflow-y: auto;
  padding: 26px 30px 28px;
  box-shadow: 0 24px 64px rgba(2, 6, 23, .35);
}
.modal h2 { margin: 0; font-size: 18.5px; line-height: 1.5; }
.modal .sub { color: var(--ink-2); font-size: 14px; line-height: 1.75; margin-top: 10px; }
.modal .risk-banner { margin-top: 18px; }
.modal .recovery { margin-top: 14px; }
.phrase-row { margin-top: 20px; }
.phrase-row label { display: block; font-size: 13.5px; margin-bottom: 9px; line-height: 1.6; }
code.phrase {
  background: #f1f5f9; border: 1px solid var(--line);
  border-radius: 6px; padding: 1px 8px;
  font-family: var(--mono); font-size: 12.5px; color: var(--ink);
}
.phrase-input {
  width: 100%; font: inherit; font-size: 15px;
  padding: 10px 13px; border: 1.5px solid var(--line-2); border-radius: 9px;
}
.phrase-input:focus { border-color: var(--accent); outline: none; box-shadow: 0 0 0 3px rgba(37, 99, 235, .15); }
.modal-error { display: none; color: #b91c1c; font-size: 13px; margin-top: 9px; }
.modal-error.show { display: block; }
.modal-actions { display: flex; justify-content: flex-end; gap: 10px; margin-top: 24px; }

/* ============ Toast ============ */
.toast {
  position: fixed; bottom: 26px; left: 50%; transform: translateX(-50%);
  background: #0f172a; color: #f1f5f9;
  padding: 10px 20px; border-radius: 10px; font-size: 13.5px;
  box-shadow: 0 12px 32px rgba(2, 6, 23, .35); z-index: 60;
}

@media (max-width: 1280px) {
  .layout { grid-template-columns: 262px minmax(0, 1fr) 280px; }
  .meta { display: none; }
}
@media (max-width: 1020px) {
  .layout { grid-template-columns: 1fr; height: auto; }
  .detail { overflow: visible; }
}

